"""Load configuration from files and strings."""

import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines

INCLUDE_DIRECTIVE = "@include"


def _read_lines(path):
    with open(path, "r", encoding="utf-8") as fh:
        return fh.read().splitlines()


def _include_target(raw):
    tokens = raw.split(None, 1)
    if not tokens or tokens[0] != INCLUDE_DIRECTIVE:
        return None
    target = tokens[1].strip() if len(tokens) > 1 else ""
    if not target:
        raise ConfigError("@include directive missing a path")
    return target


def _expand(path, lines, stack):
    base = os.path.dirname(os.path.abspath(path))
    expanded = []
    for raw in lines:
        target = _include_target(raw)
        if target is None:
            expanded.append(raw)
            continue
        inc_path = os.path.join(base, target)
        real = os.path.realpath(inc_path)
        if real in stack:
            raise ConfigError("@include cycle detected: {}".format(inc_path))
        if not os.path.isfile(inc_path):
            raise ConfigError("@include file not found: {}".format(inc_path))
        try:
            inc_lines = _read_lines(inc_path)
        except OSError as exc:
            raise ConfigError(
                "@include file could not be read: {}: {}".format(inc_path, exc)
            ) from exc
        stack.append(real)
        expanded.extend(_expand(inc_path, inc_lines, stack))
        stack.pop()
    return expanded


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` lines are replaced in place by the contents of the
    referenced file, resolved relative to the including file's directory.
    """
    lines = _read_lines(path)
    lines = _expand(path, lines, [os.path.realpath(path)])
    return parse_lines(lines)


def loads(text):
    """Parse configuration from a string."""
    return parse_lines(text.splitlines())
